"""Three Russian report pages; independent of the upstream parquet cache."""
from pathlib import Path
import json

ROOT = Path(__file__).resolve().parent


def read(name):
    return json.loads((ROOT / name).read_text(encoding="utf-8"))


def add_transfer(w):
    full = read("full_availability.json")
    audits = read("lite_chronology.json")
    results = read("results.json")["results"]
    costs = read("run_cost.json")
    w.page("Проверка хронологии", "Был ли опыт доступен при постановке задачи?",
           "В 55 из 357 задач SWEContextBench хотя бы одно размеченное исправление уже было принято в репозиторий при открытии нового запроса.")
    w.p("Каждую задачу связали с целевым pull request (PR) через метаданные авторов. Начало работы оценивали по самому раннему из открытий связанных issues, целевого PR и времени создания из релиза. Для Django использовали также исходные страницы Trac. Предыдущая работа становится доступной при слиянии её PR. Совпадающий с целевым PR исключён.")
    w.tbl(["Набор задач", "Уникальных задач", "Есть прошлая метка", "Метка того же PR"],
          [(name, full[key]["targets"], full[key]["chronology"]["past"], full[key]["same_pr"])
           for name, key in [("Lite", "lite"), ("Вне Lite", "other"), ("Полный релиз", "all")]],
          [5.2, 3.7, 4.2, 4.0], True)
    w.p("В релизе 362 строки, 357 разных ID задач и 277 целевых PR. Для всех 357 найдены точки отсечения. Определены даты слияния 1 004 из 1 007 PR опыта, включая все 300 в библиотеке Lite. Отсутствующие даты трёх PR не меняют классификацию размеченных связей.")
    w.h("Что означают прежние 75 попаданий на Lite")
    clock_rows = []
    for name, key in [("Открытие первого запроса", "issue_start"), ("Открытие целевого PR", "pr_open"),
                      ("Слияние целевого PR", "pr_merge")]:
        c = audits["clocks"][key]
        hits = c["any_qwen_hits"]
        clock_rows.append((name, c["any_gold_availability"]["past"], hits["past"], hits["nonpast"], hits.get("unknown", 0)))
    w.tbl(["Момент отсечения", "Метка доступна / 99", "Ранее / 75", "Тогда или позже / 75", "Дата неизвестна / 75"],
          clock_rows, [5.2, 3.2, 2.4, 3.3, 3.0], True)
    w.p("У предыдущего читателя Qwen 13 из 75 правильных выборов указывают на ранее принятый PR при самом раннем отсечении. При выборе последней допустимой связи — 13 из 73. Это ретроспективная классификация сохранённых выборов. В собственном статическом протоколе релиза все 75 попаданий сохраняют силу.")
    w.source("SWEContextBench · официальный релиз данных", "https://huggingface.co/datasets/jiayuanz3/SWEContextBench/tree/12c65bd15e2559bc808065565e941ee7bbbd008f")
    w.page("Проверка хронологии", "Перекрытие исправлений одного PR",
           "В 27 из 99 задач Lite среди рекомендованных источников встречается тот же PR, который авторы привязали к текущей задаче.")
    w.p("Для каждой размеченной пары сопоставили официальные патчи. Нормализовали пробелы и посчитали мультимножество добавленных и удалённых строк с путями файлов и знаком операции. Сходство — размер пересечения мультимножеств, делённый на размер объединения. Эталонные патчи открыли для этого аудита после фиксации предсказаний.")
    overlap = read("lite_patch_overlap.json")
    rows = []
    for name,key in [("Метка того же PR","gold_same_pr"),("Метка другого PR","gold_other_pr"),
                     ("Верный выбор Qwen того же PR","qwen_hits_same_pr")]:
        d = overlap[key]
        rows.append((name,d["link_pairs"], d["patch_bytes_equal"], d["changed_lines_exact"],
                     f'{d["mean_line_jaccard"]:.3f}'.replace(".", ",")))
    w.tbl(["Выборка пар", "Пар", "Равны байты", "Равны изменения", "Среднее сходство"],
          rows,[5.8,1.6,3.0,3.3,3.4],True)
    w.p("У трёх задач две допустимые связи, поэтому на 99 задач приходится 102 пары. Последняя строка — подмножество первой. Содержание человеческого патча и краткого описания в памяти агента различается. Перекрытие изменений указывает на близость задач и помогает понять, какой опыт измеряет статический тест.")
    w.h("Какой вопрос можно проверять дальше")
    w.p("Сравнить два вида памяти на последовательностях отдельных PR: поиск ранее решённого похожего инцидента и перенос проверенной процедуры в другой инцидент. Полезность первой оценивается поиском доступной записи. Для второй нужен агент, который получает запись при решении следующей задачи, и скрытые исполняемые тесты.")
    w.p("Время слияния выбранo как воспроизводимый момент доступности завершённого исправления. Переписка и отдельные коммиты могли появляться раньше. Даже при более мягком правиле «предыдущий PR уже открыт» доступная метка имеется лишь у 18 из 99 задач. Время записи самой агентской траектории и исторические версии текстов issues в релизе не зафиксированы.")
    w.source("SWEContextBench · метаданные целевых задач и PR",
             "https://github.com/jiayuanz3/SWEContextBench/tree/12ad6ab14e18e9378e1e293c9edbc3f7ce43d27b")
    w.page("Эксперимент с записью опыта", "Что сохранять из прошлой правки",
           "На 258 задачах вне Lite карточка из описания сбоя и признаков правки дала 26 первых попаданий. Поиск по одному описанию дал 25.")
    w.p("В библиотеке 1 007 опубликованных человеческих исправлений. На каждой задаче доступны завершённые до её открытия PR того же репозитория. BM25 использует статистику только допущенных кандидатов. В карточку входят до 192 слов старого issue и до 64 путей, заголовков фрагментов и идентификаторов старого патча. Исходники репозитория для записи не индексировались.")
    methods = [("Описание сбоя, 256 слов", "issue256"), ("Описание сбоя, 192 слова", "issue192"),
               ("Только признаки правки", "edit64"), ("Описание и признаки правки", "card"),
               ("Описание и чужая правка", "placebo"), ("По дате слияния PR", "recency"),
               ("Раздельный поиск и слияние рангов", "separate")]
    table = []
    for name,k in methods:
        d=results["repo_time"]["all"]["arms"][k]
        table.append((name, d["hits1"], d["hits5"], f'{d["mrr"]:.3f}'.replace(".",","),
                      results["repo_release"]["all"]["arms"][k]["hits1"]))
    w.tbl(["Запись и способ поиска", "Hit@1", "Hit@5", "MRR", "Hit@1 без отсечения"],
          table,[6.6,2.1,2.1,2.2,4.1],True)
    w.p("Знаменатель во всех столбцах 258. Во временном режиме размеченный опыт доступен для 38 задач, медиана пула 4. Для карточки против 256 слов имеем два улучшения и одну потерю, +0,39 п.п. с 95% кластерным интервалом по 39 репозиториям от −0,94 до +1,97 п.п. Точный парный p = 1,00. На 31 задаче с доступной меткой и ≥5 кандидатами результаты 21 против 20.")
    w.p("Без отсечения времени карточка дала 151 против 141 (+3,88 п.п., интервал от −1,36 до +8,68). Раздельное ранжирование дало 28 против 25 во временном режиме, это вторичное сравнение. При переносе на все репозитории сразу карточка дала 27 против 25, медиана пула 445,5.")
    w.p(f'Формирование карточек и ранжирование семью способами заняли {costs["total_seconds"]:.1f} с на CPU при прогретом кэше. Записи занимали 1,286 МБ текста против 1,215 МБ описаний. Решатель и GPU в этом опыте не использовались. Задачи вне Lite раньше оценивались с меньшей библиотекой. Это проверка поиска в той же семье бенчмарков.','Caption')

